INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4bae9977-bcbf-4363-8993-5c79976aa325', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 7, 'O Transbordamento no Outro', NULL, '{"intro": "O encontro com Deus deve resultar no encontro com o irm\u00e3o.", "prayer": "Seja o canal por onde o amor dEle flui.", "practice": "Sirva a algu\u00e9m de forma oculta hoje.", "reflection": "A m\u00edstica que n\u00e3o serve n\u00e3o \u00e9 m\u00edstica, \u00e9 ego\u00edsmo.", "journal_prompt": "Como o seu encontro com Deus mudou o seu olhar para o outro?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;